/* ---------- Color scheme ---------- */
:root {
  /* Follow the OS by default; the header toggle rewrites <meta name="color-scheme">. */
  color-scheme: light dark;

  &:has(> head > meta[name="color-scheme"][content="dark"]) { color-scheme: dark; }
  &:has(> head > meta[name="color-scheme"][content="light"]) { color-scheme: light; }

  /* Raw palette */
  --bg-light: #f6f7f9;          --bg-dark: #111318;
  --text-light: #1d1f23;        --text-dark: #e6e8eb;
  --surface-light: white;       --surface-dark: #1c1f26;
  --border-light: #eee;         --border-dark: #2e333d;
  --muted-light: #e5e7eb;       --muted-dark: #343a46;
  --header-bg-light: #1d4ed8;   --header-bg-dark: #1e3a8a;
  --error-light: #dc2626;       --error-dark: #f87171;
  --error-bg-light: #fef2f2;    --error-bg-dark: #3b1518;
  --shadow-light: rgb(0 0 0 / 0.1); --shadow-dark: rgb(0 0 0 / 0.5);

  /* Fallback for browsers without light-dark(): light by default… */
  --bg: var(--bg-light);
  --text: var(--text-light);
  --surface: var(--surface-light);
  --border: var(--border-light);
  --muted: var(--muted-light);
  --header-bg: var(--header-bg-light);
  --error: var(--error-light);
  --error-bg: var(--error-bg-light);
  --shadow: var(--shadow-light);
}

/* …dark when the OS is dark (unless pinned to light) or when pinned to dark. */
@media (prefers-color-scheme: dark) {
  :root:not(:has(> head > meta[name="color-scheme"][content="light"])) {
    --bg: var(--bg-dark);
    --text: var(--text-dark);
    --surface: var(--surface-dark);
    --border: var(--border-dark);
    --muted: var(--muted-dark);
    --header-bg: var(--header-bg-dark);
    --error: var(--error-dark);
    --error-bg: var(--error-bg-dark);
    --shadow: var(--shadow-dark);
  }
}
:root:has(> head > meta[name="color-scheme"][content="dark"]) {
  --bg: var(--bg-dark);
  --text: var(--text-dark);
  --surface: var(--surface-dark);
  --border: var(--border-dark);
  --muted: var(--muted-dark);
  --header-bg: var(--header-bg-dark);
  --error: var(--error-dark);
  --error-bg: var(--error-bg-dark);
  --shadow: var(--shadow-dark);
}

/* Modern browsers: light-dark() follows the computed color-scheme directly. */
@supports (color: light-dark(white, black)) {
  :root, :root:has(> head > meta) {
    --bg: light-dark(var(--bg-light), var(--bg-dark));
    --text: light-dark(var(--text-light), var(--text-dark));
    --surface: light-dark(var(--surface-light), var(--surface-dark));
    --border: light-dark(var(--border-light), var(--border-dark));
    --muted: light-dark(var(--muted-light), var(--muted-dark));
    --header-bg: light-dark(var(--header-bg-light), var(--header-bg-dark));
    --error: light-dark(var(--error-light), var(--error-dark));
    --error-bg: light-dark(var(--error-bg-light), var(--error-bg-dark));
    --shadow: light-dark(var(--shadow-light), var(--shadow-dark));
  }
}

/* ---------- Layout ---------- */
body { font-family: system-ui, sans-serif; margin: 0; background: var(--bg); color: var(--text); }
.top { background: var(--header-bg); color: white; padding: 1rem 2rem; display: flex; flex-wrap: wrap; gap: 1rem; align-items: center; justify-content: space-between; }
.top h1 { margin: 0; }
main { max-width: 640px; margin: 2rem auto; display: grid; gap: 1.5rem; }
.card { background: var(--surface); border-radius: 8px; padding: 1.25rem; box-shadow: 0 1px 3px var(--shadow); }
form label { display: block; margin-top: 0.75rem; font-weight: 600; }
form input { width: 100%; padding: 0.5rem; box-sizing: border-box; }
input:invalid { border: 2px solid var(--error); background: var(--error-bg); }
.help-icon { display: inline-grid; place-items: center; width: 1.2em; height: 1.2em; border-radius: 50%; background: var(--muted); font-size: 0.8em; cursor: help; }
#task-list { list-style: none; margin: 0; }
#task-list li { display: flex; justify-content: space-between; padding: 0.5rem 0; border-bottom: 1px solid var(--border); }
button { cursor: pointer; }

/* ---------- Theme switch (segmented control) ---------- */
.theme-switch { display: flex; margin: 0; padding: 0; border: 1px solid rgb(255 255 255 / 0.6); border-radius: 999px; overflow: hidden; }
.theme-switch label { display: flex; align-items: center; gap: 0.25em; padding: 0.35rem 0.8rem; font-size: 0.875rem; cursor: pointer; }
.theme-switch label + label { border-inline-start: 1px solid rgb(255 255 255 / 0.6); }
.theme-switch input { position: absolute; opacity: 0; pointer-events: none; }
.theme-switch label:has(input:checked) { background: white; color: #1e3a8a; font-weight: 600; }
.theme-switch label:has(input:focus-visible) { outline: 2px solid white; outline-offset: -4px; }
.system-now { opacity: 0.75; font-weight: 400; }
/* Show the current OS preference next to "System" — pure CSS, stays live. */
.system-now[data-scheme="dark"] { display: none; }
@media (prefers-color-scheme: dark) {
  .system-now[data-scheme="light"] { display: none; }
  .system-now[data-scheme="dark"] { display: inline; }
}

.visually-hidden { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }

